import {spawnSync} from 'node:child_process';

describe('weather tool example', () => {
  it('does not fabricate a fallback location outside the registry contract', () => {
    const script =
      "import('./example/weather-tool.ts').then(async ({executeWeather}) => console.log(await executeWeather({})))";
    const execution = spawnSync(process.execPath, ['--import', 'tsx', '--input-type=module', '--eval', script], {
      encoding: 'utf8',
    });
    const result = JSON.parse(execution.stdout.trim()) as Record<string, unknown>;

    expect({status: execution.status, hasLocation: Object.hasOwn(result, 'location')}).toEqual({
      status: 0,
      hasLocation: false,
    });
  });
});
import {ToolRegistry} from './registry.js';

const REQUIRED_LOCATION_TOOL = {
  name: 'weather',
  description: 'Gets the weather',
  inputSchema: {
    type: 'object',
    properties: {location: {type: 'string'}},
    required: ['location'],
  },
};

describe('ToolRegistry', () => {
  it('returns a required-property rejection before invoking the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(REQUIRED_LOCATION_TOOL, async () => {
      executorCalls += 1;
      return 'sunny';
    });

    const response = await registry.execute('weather', {});

    expect({response, executorCalls}).toEqual({
      response: {result: 'Invalid tool input: location is required'},
      executorCalls: 0,
    });
  });

  it('passes valid input with an undeclared property through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', units: 'metric'};
    const received: Record<string, unknown>[] = [];
    registry.register(REQUIRED_LOCATION_TOOL, async toolInput => {
      received.push(toolInput);
      return 'sunny';
    });

    await registry.execute('weather', input);

    expect(received).toEqual([input]);
  });

  it('names the complete path of a nested missing required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'local_weather',
        description: 'Gets weather for a city',
        inputSchema: {
          type: 'object',
          properties: {
            address: {
              type: 'object',
              properties: {city: {type: 'string'}},
              required: ['city'],
            },
          },
          required: ['address'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('local_weather', {address: {}});

    expect(response).toEqual({result: 'Invalid tool input: address.city is required'});
  });

  it('names a wrong-typed property and expected type without returning its value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'identity_lookup',
        description: 'Looks up an identity',
        inputSchema: {
          type: 'object',
          properties: {identity: {type: 'string'}},
          required: ['identity'],
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('identity_lookup', {identity: 123456789});

    expect({
      result: response.result,
      leaksValue: response.result.includes('123456789'),
    }).toEqual({
      result: 'Invalid tool input: identity must be a string',
      leaksValue: false,
    });
  });

  it('names an enum property and its allowed choices without returning its value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather_units',
        description: 'Gets weather in the requested units',
        inputSchema: {
          type: 'object',
          properties: {units: {type: 'string', enum: ['celsius', 'fahrenheit']}},
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather_units', {units: 'kelvin'});

    expect({result: response.result, leaksValue: response.result.includes('kelvin')}).toEqual({
      result: 'Invalid tool input: units must be one of celsius, fahrenheit',
      leaksValue: false,
    });
  });

  it('compiles the current schema from a function-valued definition before execution', async () => {
    const registry = new ToolRegistry();
    const schema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
    };
    let currentSchema = schema;
    let executorCalls = 0;
    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Changes schema between calls',
        inputSchema: currentSchema,
      }),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    await registry.execute('dynamic_weather', {location: 'Berlin'});
    schema.properties = {location: {type: 'not-a-json-schema-type'}};
    await registry.execute('dynamic_weather', {location: 'Berlin'});
    currentSchema = {...schema};

    let thrown: unknown;
    try {
      await registry.execute('dynamic_weather', {location: 'Berlin'});
    } catch (error) {
      thrown = error;
    }

    expect({
      executorCalls,
      error: thrown instanceof Error ? thrown.message : String(thrown),
    }).toEqual({executorCalls: 2, error: expect.stringMatching(/dynamic_weather/)});
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- The worked weather-tool executor relies on registry validation and does not fabricate a location when called without one ([validated by: does not fabricate a fallback location outside the registry contract](../../src/orchestration/tools/weather-tool.test.ts#L4)).
- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16); [validated by: returns a required-property rejection before invoking the executor](../../src/orchestration/tools/registry.test.ts#L14)).
- A missing required property nested inside another object is identified by its complete property path, including its parent objects ([validated by: names the complete path of a nested missing required property](../../src/orchestration/tools/registry.test.ts#L44)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46); [validated by: names a wrong-typed property and expected type without returning its value](../../src/orchestration/tools/registry.test.ts#L70)).
- When `input` supplies a string outside a property's declared `enum`, the rejection names the property and its allowed choices without returning the offending value ([validated by: names an enum property and its allowed choices without returning its value](../../src/orchestration/tools/registry.test.ts#L96)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with an undeclared property through unchanged exactly once](../../src/orchestration/tools/registry.test.ts#L30)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: compiles the current schema from a function-valued definition before execution](../../src/orchestration/tools/registry.test.ts#L118)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
